sys_script_client.script:
function onLoad() {

    //Type appropriate comment here, and begin script below
    //MSSCUSTODY 5981 - Hide/Show Bulk field group is value is present

    var bulk_field = g_form.getValue('bulk_id.bulk_field_group');
    var ownBusiness = g_scratchpad.owningBus; // MSSCUSTODY-8718
    if (bulk_field) {
        hideAllFields();
        g_form.setDisplay('bulk_id.bulk_field_group', true);
        var field_group = [];
        if (bulk_field == 'customer_reference') {
            field_group = ['bulk_id.customer_reference'];
        } else if (bulk_field == 'trade_settl_date') {
            field_group = ['bulk_id.amend_trade_date', 'bulk_id.settlement_date', 'amend_swh']; // MSSCUSTODY-7898 - Added SWH
        } else if (bulk_field == 'cash_hold_indicator') {
            field_group = ['bulk_id.amend_cash_hold_indicator'];
        } else if (bulk_field == 'beneficiary_details') {
            field_group = ['bulk_id.amend_a_c_of_client', 'bulk_id.amend_deliverer_custodian_bic_receiver_custodian_bic', 'bulk_id.amend_seller_bic_buyer_bic', 'bulk_id.amend_place_of_settlement_bic', 'bulk_id.amend_receiver_custodian_bic', 'bulk_id.amend_buyer_bic']; // MSSCUSTODY-7159 - Added Buyer (BIC) and Receiver Custodian (BIC) field
        } else if (bulk_field == 'counterparty_details') {
            field_group = ['bulk_id.counterparty_reference', 'bulk_id.amend_payment_method', 'bulk_id.amend_counterparty_code', 'bulk_id.amend_counterparty_settlement_account_number', 'bulk_id.amend_counterparty_code_ref']; // MSSCUSTODY 5862 - Added remote table fields
        } else if (bulk_field == 'location_gdi') {
            field_group = ['bulk_id.amend_location_code', 'bulk_id.amend_gdi_indicator'];
        } else if (bulk_field == 'hmi_indicator​') {
            field_group = ['bulk_id.amend_hmi_indicator'];
        } else if (bulk_field == 'script_hold_indicator') {
            field_group = ['bulk_id.amend_script_hold_indicator'];
        } else if (bulk_field == 'security_id') {
            field_group = ['bulk_id.security_id_sec_id', 'bulk_id.amend_security_id_sec_id_ref']; // MSSCUSTODY 5862 - Added remote table fields
        } else if (bulk_field == 'amendment_charges') {
            field_group = ['bulk_id.amend_charges_ccy', 'bulk_id.amend_charges_amt', 'bulk_id.amend_charges_type'];
        } else if (bulk_field == 'fa') {
            field_group = ['bulk_id.amend_fa'];
        } else if (bulk_field == 'iss') {
            field_group = ['bulk_id.amend_iss'];
        }


        //if ((parseInt(g_form.getValue('bulk_id.active_trade_count')) > 1)) {
        field_group.forEach(function(field) {
            g_form.setDisplay(field, true);
        });
        if ((g_form.getValue('trade_task_type') == 'Maker' && (g_form.getValue('state') == '3' || (g_form.getValue('state') == '2' && multipleMaker == true))) || g_form.getValue('trade_task_type') == 'Checker') {
            field_group.forEach(function(field) {
                g_form.setReadOnly(field, true);
                g_form.setReadOnly('bulk_id.bulk_field_group', true);
                //6894
                if (g_form.getValue('bulk_id.bulk_field_group') != '') {
                    g_form.setReadOnly('outcome', true);
                }
            });
            g_form.setReadOnly('decision', true);
        }
        //}
        return;
    } else {
        g_form.setDisplay('bulk_id.bulk_field_group', false);
    }

    //-----------8128-------
    var settDate = false;

    var dateCheck = new GlideAjax('global.hsbcTimeUtils'); // to compare sett date with todays date
    dateCheck.addParam('sysparm_name', 'dateComparisonCheck');
    dateCheck.addParam('sysparm_settDate', g_form.getValue('bulk_id.settlement_date'));
    dateCheck.getXMLAnswer(function(result) {
        if (result.toString() == 'true') {
            settDate = true;
        }
    });
    //-----------8128-------

    var eligbleCheck = new GlideAjax('x_hsb11_mss_c_proc.MSSCustodyAmendUtils');
    eligbleCheck.addParam('sysparm_name', 'evalAmendEligibility');
    //eligbleCheck.addParam('sysparm_recOutcome', g_form.getValue('outcome'));
    eligbleCheck.addParam('sysparm_recOutcome', g_scratchpad.tskoutcome); // MSSCUSTODY-7419
    eligbleCheck.addParam('sysparm_recSysID', g_form.getUniqueValue());
    eligbleCheck.addParam('sysparm_tableName', 'x_hsb11_mss_c_proc_mss_custody_task');
    eligbleCheck.getXMLAnswer(function(check) {
        if (check.toString() === 'true') {
            // Stage-by-stage evaluation
            displayAllFields();
            if (ownBusiness.indexOf("SG") <= -1) {
                g_form.removeOption('bulk_id.amend_gdi_indicator', 'Hold by Bypass');
            } else {
                g_form.addOption('bulk_id.amend_gdi_indicator', 'Hold by Bypass', 'Hold by Bypass');
            }
            //MSSCUSTODY-5980 - introduced trade fields on form for amend
            g_form.setDisplay('trade_id.transaction_type', true);
            g_form.setDisplay('trade_id.security_account_type', true);
            g_form.setDisplay('trade_id.securities_account', true);
            g_form.setDisplay('trade_id.account_name', true);
            g_form.setDisplay('trade_id.associated_sub_account', true);
            g_form.setDisplay('trade_id.si_purpose_code', true);
            g_form.setDisplay('trade_id.si_payment_indicator', true);

            g_form.setReadOnly('trade_id.transaction_type', true);
            g_form.setReadOnly('trade_id.security_account_type', true);
            g_form.setReadOnly('trade_id.securities_account', true);
            g_form.setReadOnly('trade_id.account_name', true);
            g_form.setReadOnly('trade_id.associated_sub_account', true);
            g_form.setReadOnly('trade_id.si_purpose_code', true);
            g_form.setReadOnly('trade_id.si_payment_indicator', true);
            var transactionType = g_form.getValue('trade_id.transaction_type');

            var getData = g_form.getReference('trade_id', getTradeData);

            function getTradeData(getData) {

                var switchIndicator = getData.switch_indicator.toString()
                //var switchIndicator = g_form.getValue('bulk_id.amend_switch_indicator') || 'Y';
                var legacyStatus = g_form.getValue('trade_id.legacy_status');
                var legacyPrevStatus = g_form.getValue('trade_id.legacy_previous_status');

                evaluateStage1(transactionType); // Evaluate stage 1 - Transaction type
                evaluateStage2(switchIndicator); // Evaluate stage 2 - Switch or Non-Switch
                evaluateStage3(legacyStatus, legacyPrevStatus, switchIndicator); // Evaluate stage 3 - Legacy status
                if (g_form.getValue('bulk_id.amend_charges_type') != 'U') {
                    g_form.setReadOnly('bulk_id.amend_charges_ccy', true);
                    g_form.setReadOnly('bulk_id.amend_charges_amt', true);
                } else if (g_form.getValue('bulk_id.amend_charges_type') == 'U') {
                    g_form.setReadOnly('bulk_id.amend_charges_ccy', false);
                    g_form.setReadOnly('bulk_id.amend_charges_amt', true);
                }
                if (g_form.getValue('bulk_id.amend_charges_ccy') == '') {
                    g_form.setReadOnly('bulk_id.amend_charges_amt', true);
                } else if (g_form.getValue('bulk_id.amend_charges_ccy') != '') {
                    g_form.setReadOnly('bulk_id.amend_charges_amt', false);
                }
                if (g_form.getValue('bulk_id.amend_settlement_currency') == '') {
                    g_form.setReadOnly('bulk_id.amend_settlement_amount', true);
                } else if (g_form.getValue('bulk_id.amend_settlement_currency') != '') {
                    g_form.setReadOnly('bulk_id.amend_settlement_amount', false);
                }
                if (g_form.getValue('bulk_id.amend_switch_indicator') != 'N') {
                    g_form.setReadOnly('bulk_id.counterparty_reference', true);
                    g_form.setDisplay('bulk_id.amend_convert_to_account_switching', false);
                } else if (g_form.getValue('bulk_id.amend_switch_indicator') == 'N') {
                    g_form.setReadOnly('bulk_id.counterparty_reference', false);
                    g_form.setDisplay('bulk_id.amend_convert_to_account_switching', true);
                }
                if (g_form.getValue('bulk_id.amend_payment_method') != 'TFR') {
                    g_form.setReadOnly('bulk_id.amend_counterparty_settlement_account_number', true);
                } else if (g_form.getValue('bulk_id.amend_payment_method') == 'TFR') {
                    g_form.setReadOnly('bulk_id.amend_counterparty_settlement_account_number', false);
                }
                if ((g_form.getValue('bulk_id.amend_convert_to_account_switching') != 'Y' && g_form.getValue('bulk_id.amend_switch_indicator') != 'Y') || g_form.getValue('bulk_id.amend_switch_indicator') == '') {
                    g_form.setReadOnly('bulk_id.amend_switch_account_ref', true);
                    g_form.setDisplay('bulk_id.amend_suspense_account_number', false);
                    g_form.setReadOnly('bulk_id.amend_suspense_account_number', true);
                    g_form.setReadOnly('bulk_id.amend_counterparty_code', false);
                    g_form.setReadOnly('bulk_id.amend_payment_method', false);
                    g_form.setReadOnly('bulk_id.amend_counterparty_settlement_account_number', false);
                } else if (g_form.getValue('bulk_id.amend_convert_to_account_switching') == 'Y' || g_form.getValue('bulk_id.amend_switch_indicator') == 'Y') {
                    g_form.setDisplay('bulk_id.amend_switch_account_ref', true);
                    g_form.setDisplay('bulk_id.amend_switch_account', true); // MSSCUSTODY-6827 
                    g_form.setReadOnly('bulk_id.amend_switch_account', true); // MSSCUSTODY-6827 
                    g_form.setDisplay('bulk_id.amend_suspense_account_number', false);
                    g_form.setReadOnly('bulk_id.amend_suspense_account_number', true);
                    g_form.setReadOnly('bulk_id.amend_payment_method', true);
                    g_form.setReadOnly('bulk_id.amend_counterparty_code', true);
                    g_form.setReadOnly('bulk_id.amend_counterparty_settlement_account_number', true);
                    if (g_form.getValue('bulk_id.amend_switch_account') == '') {
                        g_form.setReadOnly('bulk_id.amend_switch_account_ref', false);
                        //g_form.setMandatory('bulk_id.amend_switch_account_ref', true);
                    } else {
                        g_form.setReadOnly('bulk_id.amend_switch_account_ref', true);
                    }
                }
                //-----------8128-------SWH
                if ((g_form.getValue('bulk_id.amend_convert_to_account_switching') == 'Y' || g_form.getValue('bulk_id.amend_switch_indicator') == 'Y')) {
                    g_form.setDisplay('bulk_id.amend_swh', true);
                    g_form.setReadOnly('bulk_id.amend_swh', true);
                    if (ownBusiness == 'DCC JP' && settDate == true && g_form.getValue('bulk_id.amend_location_code') == 'BOJ') {
                        g_form.setReadOnly('bulk_id.amend_swh', false);
                    } else if (ownBusiness != 'DCC JP' || settDate == false || g_form.getValue('bulk_id.amend_location_code') != 'BOJ') {
                        g_form.setReadOnly('bulk_id.amend_swh', true);
                    }
                } else if ((g_form.getValue('bulk_id.amend_convert_to_account_switching') != 'Y' && g_form.getValue('bulk_id.amend_switch_indicator') != 'Y')) {
                    g_form.setDisplay('bulk_id.amend_swh', false);
                }
                //-----------8128-------SWH
                //-----------8173-------Switch Ref
                if (g_form.getValue('bulk_id.amend_convert_to_account_switching') != 'Y' || g_form.getValue('bulk_id.amend_trade_switch_reference') != '') {
                    g_form.setReadOnly('bulk_id.amend_switch_reference', true);
                } else if (g_form.getValue('bulk_id.amend_convert_to_account_switching') == 'Y' && g_form.getValue('bulk_id.amend_trade_switch_reference') == '') {
                    g_form.setReadOnly('bulk_id.amend_switch_reference', false);
                }
                //-----------8173-------Switch Ref

                if ((g_form.getValue('trade_task_type') == 'Checker')) {
                    readOnlyAllFields();
                }

            }

        } else {
            // If not eligible, hide all fields
            hideAllFields();
        }

    });

}

//Displays all fields by setting them to visible and editable.
function displayAllFields() {
    var fields = getAllFields();
    fields.forEach(function(field) {
        g_form.setDisplay(field, true);
        g_form.setReadOnly(field, false);
    });
}

function readOnlyAllFields() {
    var fields = getAllFields();
    fields.forEach(function(field) {
        g_form.setReadOnly(field, true);
    });
}

//Hides all fields
function hideAllFields() {
    var fields = getAllFields();
    fields.forEach(function(field) {
        g_form.setDisplay(field, false);
    });
}

// Returns a list of all fields.

function getAllFields() {
    return [
        'bulk_id.security_id_sec_id',
        'bulk_id.amend_trade_date',
        'bulk_id.settlement_date',
        'bulk_id.amend_deal_price',
        'bulk_id.amend_deal_currency',
        'bulk_id.amend_settlement_currency',
        'bulk_id.amend_settlement_amount',
        'bulk_id.counterparty_reference',
        'bulk_id.customer_reference',
        'bulk_id.amend_location_code',
        'bulk_id.amend_hmi_indicator',
        'bulk_id.amend_script_hold_indicator',
        'bulk_id.amend_cash_hold_indicator',
        'bulk_id.amend_gdi_indicator',
        'bulk_id.amend_payment_method',
        'bulk_id.amend_switch_indicator',
        'bulk_id.amend_switch_account',
        'bulk_id.amend_counterparty_code',
        'bulk_id.amend_deliverer_custodian_bic_receiver_custodian_bic', // MSSCUSTODY-7159 - Deliver custodian field
        'bulk_id.amend_receiver_custodian_bic', // MSSCUSTODY-7159 - Added Receiver custodian field
        'bulk_id.amend_seller_bic_buyer_bic', // MSSCUSTODY-7159 - Seller BIC field
        'bulk_id.amend_buyer_bic', // MSSCUSTODY-7159 - Added Buyer BIC field
        'bulk_id.amend_place_of_settlement_bic',
        'bulk_id.amend_suspense_account_number',
        'bulk_id.amend_counterparty_settlement_account_number',
        'bulk_id.amend_convert_to_account_switching',
        'bulk_id.amend_a_c_of_client',
        'bulk_id.amend_charges_ccy',
        'bulk_id.amend_charges_amt',
        'bulk_id.amend_charges_type',
        'bulk_id.amend_nssc',
        'bulk_id.amend_switch_account_ref',
        'bulk_id.amend_counterparty_code_ref',
        'bulk_id.amend_security_id_sec_id_ref',
        'trade_id.transaction_type',
        'trade_id.security_account_type',
        'trade_id.securities_account',
        'trade_id.account_name',
        'trade_id.associated_sub_account',
        'trade_id.si_purpose_code',
        'trade_id.si_payment_indicator',
        'bulk_id.amend_si_purpose_code', //6843
        'bulk_id.amend_propriaty_code',
        'bulk_id.amend_data_source_scheme',
        'bulk_id.amend_iss', //7761
        'bulk_id.amend_swh', // MSSCUSTODY-7898
        'bulk_id.amend_fa',
        'bulk_id.amend_switch_reference'
    ];
}

// Evaluates Stage 1: Based on Transaction Type.
function evaluateStage1(transactionType) {
    var ownBusiness = g_scratchpad.owningBus;
    var stage1Fields = {
        'bulk_id.amend_deal_price': ['RVP', 'DVP'],
        'bulk_id.amend_deal_currency': ['RVP', 'DVP'],
        'bulk_id.amend_payment_method': ['RVP', 'DVP'],
        'bulk_id.amend_settlement_currency': ['RVP', 'DVP'],
        'bulk_id.amend_settlement_amount': ['RVP', 'DVP'],
        'bulk_id.amend_suspense_account_number': ['RVP', 'DVP'],
        'bulk_id.amend_script_hold_indicator': ['DVP', 'DFP'],
        'bulk_id.amend_cash_hold_indicator': ['RVP'],
        'bulk_id.amend_nssc': ['DVP', 'DFP'],
        'bulk_id.amend_counterparty_settlement_account_number': ['RVP', 'DVP'],
        'bulk_id.amend_fa': ['RVP']
    };


    // Iterate over each field and determine visibility based on transactionType
    Object.keys(stage1Fields).forEach(function(field) {
        var applicableTransactionTypes = stage1Fields[field];
        if (applicableTransactionTypes.includes(transactionType)) {
            g_form.setDisplay(field, true); // Show the field if transactionType matches

        } else {
            g_form.setDisplay(field, false); // Hide the field if transactionType does not match
            if (g_form.getValue('state') == 1 || g_form.getValue('state') == 2) {
                //g_form.clearValue(field);
            }
        }
    });


}


function evaluateStage2(switchIndicator) {
    var ownBusiness = g_scratchpad.owningBus;
    // Configuration for Stage 2 fields switch and non- switch trades
    var stage2Fields = {
        'bulk_id.security_id_sec_id': {
            N: 'show',
            Y: 'show'
        }, // Security ID
        'bulk_id.amend_security_id_sec_id_ref': {
            N: 'show',
            Y: 'show'
        },
        'bulk_id.amend_trade_date': {
            N: 'show',
            Y: 'show'
        }, // Trade Date
        'bulk_id.settlement_date': {
            N: 'show',
            Y: 'show'
        }, // Settlement Date
        'bulk_id.amend_deal_currency': {
            N: 'show',
            Y: 'hide'
        }, // Deal Currency / Price
        'bulk_id.amend_deal_price': {
            N: 'show',
            Y: 'hide'
        },
        'bulk_id.amend_settlement_currency': {
            N: 'show',
            Y: 'show'
        }, // Settlement Currency
        'bulk_id.amend_settlement_amount': {
            N: 'show',
            Y: 'show'
        }, // Settlement Amount
        'bulk_id.counterparty_reference': {
            N: 'show',
            Y: 'hide'
        }, // Counterparty Reference
        'bulk_id.customer_reference': {
            N: 'show',
            Y: 'show'
        }, // Customer Reference
        'bulk_id.amend_location_code': {
            N: 'show',
            Y: 'show'
        }, // Location Code
        'bulk_id.amend_hmi_indicator': {
            N: 'show',
            Y: 'show'
        }, // HMI Indicator
        'bulk_id.amend_script_hold_indicator': {
            N: 'show',
            Y: 'show'
        }, // Scrip Hold Indicator
        'bulk_id.amend_cash_hold_indicator': {
            N: 'show',
            Y: 'show'
        }, // Cash Hold Indicator
        'bulk_id.amend_gdi_indicator': {
            N: 'show',
            Y: 'show'
        }, // GDI Indicator
        'bulk_id.amend_payment_method': {
            'N': 'show',
            'Y': 'hide'
        }, // Payment Method

        // MSSCUSTODY-6644 - Added for controlling visibility based on switch indicator
        'bulk_id.amend_convert_to_account_switching': {
            'N': 'show',
            'Y': 'hide'
        }, // Convert to account Switching

        'bulk_id.amend_switch_account': {
            N: 'hide',
            Y: 'show'
        }, // Switch Account
        'bulk_id.amend_switch_account_ref': {
            N: 'hide',
            Y: 'show'
        }, // Switch Account
        'bulk_id.amend_suspense_account_number': {
            N: 'hide',
            Y: 'show'
        }, // Suspense Account Number
        'bulk_id.amend_counterparty_code': {
            N: 'show',
            Y: 'hide'
        }, // Counterparty Code
        'bulk_id.amend_counterparty_code_ref': {
            N: 'show',
            Y: 'hide'
        },
        'bulk_id.amend_counterparty_settlement_account_number': {
            N: 'show',
            Y: 'hide'
        }, // Counterparty Settlement Account Number
        'bulk_id.amend_a_c_of_client': {
            N: 'show',
            Y: 'show'
        }, // A/c of Client
        'bulk_id.amend_deliverer_custodian_bic_receiver_custodian_bic': {
            N: 'show',
            Y: 'show'
        }, // Deliverer Custodian (BIC) 
        'bulk_id.amend_receiver_custodian_bic': {
            N: 'show',
            Y: 'show'
        }, // MSSCUSTODY-7159 - Receiver Custodian (BIC)
        'bulk_id.amend_seller_bic_buyer_bic': {
            N: 'show',
            Y: 'show'
        }, // Seller (BIC) 
        'bulk_id.amend_buyer_bic': {
            N: 'show',
            Y: 'show'
        }, // MSSCUSTODY-7159 - Buyer (BIC)
        'bulk_id.amend_place_of_settlement_bic': {
            N: 'show',
            Y: 'show'
        }, // Place of Settlement (BIC)
        'bulk_id.amend_charges_type': {
            N: 'show',
            Y: 'show'
        }, // Amend Charges Type
        'bulk_id.amend_charges_ccy': {
            N: 'show',
            Y: 'show'
        }, // Amend Charges CCY
        'bulk_id.amend_charges_amt': {
            N: 'show',
            Y: 'show'
        }, // Amend Charges AMT
        'bulk_id.amend_nssc': {
            N: 'show',
            Y: 'show'
        }, // NSSC
        'bulk_id.amend_si_purpose_code': {
            N: 'show',
            Y: 'show'
        }, // Si Purpose Code 7294
        'bulk_id.amend_data_source_scheme': {
            N: 'show',
            Y: 'hide'
        }, // Data source scheme 7294 
        'bulk_id.amend_propriaty_code': {
            N: 'show',
            Y: 'hide'
        }, // propriaty code 7294
        'bulk_id.amend_iss': {
            N: 'show',
            Y: 'show'
        }, // ISS 7761
        'bulk_id.amend_swh': {
            N: 'hide',
            Y: 'show'
        }, // MSSCUSTODY-7898
        'bulk_id.amend_fa': {
            N: 'show',
            Y: 'hide'
        },
        'bulk_id.amend_switch_reference': {
            N: 'show',
            Y: 'hide'
        },
    };

    Object.keys(stage2Fields).forEach(function(field) {
        var visibility = stage2Fields[field][switchIndicator]; // Get visibility for the current switchIndicator
        if (visibility === 'hide') {
            g_form.setDisplay(field, false); // Hide the field if the value is 'hide'
            if (g_form.getValue('state') == 1 || g_form.getValue('state') == 2) {
                //g_form.clearValue(field);
            }
        }
        // If visibility is 'show', leave the field as is
    });
}


function evaluateStage3(legacyStatus, legacyPrevStatus, switchIndicator) {
    var ownBusiness = g_scratchpad.owningBus;
    // If legacy_status is UNEX, use legacy previous status for handling
    var effectiveStatus = legacyStatus === 'UNEX' ? legacyPrevStatus : legacyStatus;

    // Configuration for Legacy Status and fields to hide
    var legacyStatusConfig = {
        'CODE': [],
        'PRPR': [],
        'PAPP': [],
        'RCP': [],
        'PCON': [],
        'CONF (Non-Switch)': ['bulk_id.security_id_sec_id', 'bulk_id.amend_security_id_sec_id_ref', 'bulk_id.amend_location_code', 'bulk_id.amend_gdi_indicator', 'bulk_id.amend_convert_to_account_switching', 'bulk_id.amend_switch_reference'], // MSSCUSTODY-6644 - added convert to account switching

