    var columnToConsider = (effectiveStatus === 'CONF' && switchIndicator === 'Y') ? 'CONF (Switch)' :
        (effectiveStatus === 'CONF' && switchIndicator === 'N') ? 'CONF (Non-Switch)' :
        effectiveStatus; // For other legacy statuses (e.g., STTC, STTS), use the effectiveStatus directly

    // Check if the columnToConsider exists in the configuration
    if (!legacyStatusConfig[columnToConsider]) {
        columnToConsider = 'Any other status'; // Consider 'Any other status' if the status is not found
    }

    // Get the fields to make non-editable
    var fieldsToMakeNonEditable = legacyStatusConfig[columnToConsider];

    // Make the fields non-editable
    fieldsToMakeNonEditable.forEach(function(field) {
        g_form.setReadOnly(field, true);
        if (g_form.getValue('state') == 1 || g_form.getValue('state') == 2) {
            //g_form.clearValue(field);
        }
    });

    if (ownBusiness == 'DCC JP') {
        if (legacyStatus == 'CONF' && switchIndicator == 'Y') {
            g_form.setReadOnly('bulk_id.settlement_date');
        } else if (legacyStatus == 'CLRG') {
            g_form.setReadOnly('bulk_id.settlement_date');
        } else if (legacyStatus == 'MTCH') {
            g_form.setReadOnly('bulk_id.settlement_date');
        } else if (legacyStatus == 'STTC') {
            g_form.setReadOnly('bulk_id.settlement_date');
        } else if (legacyStatus == 'STTS') {
            g_form.setReadOnly('bulk_id.settlement_date');
        }
    }
